// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";
import { latencyArgType } from "../loading";
import PlaygroundExample from "./variants/playground";
const PlaygroundSource = "import { AccountSettings } from \"../helpers\";\nimport type { AccountSettingsProps } from \"../helpers\";\n\nconst Example = ({ latency, failSessions }: AccountSettingsProps) => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    {/* Remounted when the args change, so each change replays the page load. */}\n    <AccountSettings\n      key={`${String(latency)}-${String(failSessions)}`}\n      latency={latency}\n      failSessions={failSessions}\n    />\n  </div>\n);\n\nexport default Example;\n";
import OverviewExample from "./variants/overview";
const OverviewSource = "import { AccountSettings } from \"../helpers\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <AccountSettings />\n  </div>\n);\n\nexport default Example;\n";
import PartialFailureExample from "./variants/partial-failure";
const PartialFailureSource = "import { AccountSettings } from \"../helpers\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <AccountSettings failSessions />\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  parameters: {
    docs: { description: { component: "## Usage\n\nInstall the example with `npx shadcn@latest add @erbium-examples/account-settings-overview` and adapt it to your data. It composes [Avatar](/docs/components/avatar), [Badge](/docs/components/badge), [Card](/docs/components/card), [Form](/docs/components/form), [Select](/docs/components/select), [Switch](/docs/components/switch) and [Item](/docs/components/item).\n\n## Loading\n\nEach section comes from its own request and owns its own [Skeleton](/docs/components/skeleton), so a slow request holds back only its section. Every skeleton is measured from a sample of that section's data:\n\n- The profile header draws its avatar, name, badge and button at their real size.\n- The preferences form draws its fields and switches as blocks and its labels as bars. It mounts with the loaded values, so an empty form never flashes first.\n- The sessions list draws a row per sample session.\n\nCard titles and descriptions are known before any data arrives, so they render at once and only the data inside each card waits.\n\nA request that fails shows its error in its own section while the others stay usable.\n\n## External documentation\n\nSkullet measures each section's skeleton from sample data and reveals the loaded content in place.\n\n- [Skullet](https://skullet.lochie.me)" } },
    layout: "centered",
  },
} satisfies Meta;

export default { ...meta, title: "Blocks/Account Settings",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Playground: StoryObj<typeof PlaygroundExample> = {
  argTypes: { ...latencyArgType, failSessions: { control: "boolean" } },
  args: { failSessions: false, latency: 1200 },
  parameters: {
    docs: {
      description: { story: "Change the latency to see the sections answer in turn, or make the sessions request fail." },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "The profile, preferences and sessions answer one after another. Each section reveals in place as its data arrives." },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const PartialFailure: Story = {
  parameters: {
    docs: {
      description: { story: "The sessions request fails while the profile and preferences load. The error stays inside its own card, with a way to try again." },
      source: { code: PartialFailureSource },
    },
  },
  render: PartialFailureExample,
};

import { useId } from "react";
import { Avatar, AvatarFallback, AvatarImage } from "@/registry/erbium/ui/avatar";
import { Badge } from "@/registry/erbium/ui/badge";
import { Button } from "@/registry/erbium/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/registry/erbium/ui/card";
import { FieldGroup, FieldLabel } from "@/registry/erbium/ui/field";
import { Form, useAppForm } from "@/registry/erbium/ui/form";
import { Icon } from "@/registry/erbium/ui/icon";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/registry/erbium/ui/item";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/erbium/ui/select";
import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { useSimulatedFetch } from "../loading";

/*
 * An account page whose three sections come from three requests. Each section owns its loading
 * state, so a slow request holds back only its own section, and each skeleton is measured from a
 * sample of that section's data.
 */

interface Account {
  name: string;
  email: string;
  plan: string;
  avatar: string;
  memberSince: string;
}

const account: Account = {
  avatar:
    "https://images.pexels.com/photos/1681010/pexels-photo-1681010.jpeg?auto=compress&cs=tinysrgb&w=256&h=256&fit=crop",
  email: "maya@example.com",
  memberSince: "Member since March 2024",
  name: "Maya Okafor",
  plan: "Pro",
};

const sampleAccount: Account = {
  avatar: "",
  email: "name@example.com",
  memberSince: "Member since Month 0000",
  name: "Full Name",
  plan: "Plan",
};

interface Settings {
  displayName: string;
  timezone: string;
  productUpdates: boolean;
  securityAlerts: boolean;
}

const settings: Settings = {
  displayName: "Maya Okafor",
  productUpdates: false,
  securityAlerts: true,
  timezone: "Europe/Berlin",
};

const sampleSettings: Settings = {
  displayName: "Display name",
  productUpdates: true,
  securityAlerts: true,
  timezone: "Europe/Berlin",
};

interface Session {
  id: string;
  device: string;
  location: string;
  lastActive: string;
  current: boolean;
}

const sessions: Session[] = [
  {
    current: true,
    device: "Safari on macOS",
    id: "1",
    lastActive: "Active now",
    location: "Berlin, Germany",
  },
  {
    current: false,
    device: "Erbium for iOS",
    id: "2",
    lastActive: "2 hours ago",
    location: "Berlin, Germany",
  },
  {
    current: false,
    device: "Chrome on Windows",
    id: "3",
    lastActive: "Nov 2",
    location: "Lisbon, Portugal",
  },
];

const sampleSessions: Session[] = sessions.map((session, index) => ({
  ...session,
  device: "Browser on System",
  id: `sample-${index}`,
  lastActive: "Some time ago",
  location: "City, Country",
}));

const timezones = [
  { label: "Berlin (GMT+1)", value: "Europe/Berlin" },
  { label: "Lisbon (GMT)", value: "Europe/Lisbon" },
  { label: "New York (GMT−5)", value: "America/New_York" },
  { label: "Tokyo (GMT+9)", value: "Asia/Tokyo" },
];

const ProfileHeader = ({ value }: { value: Account }) => (
  <div className="flex flex-wrap items-center gap-group">
    <Avatar size="lg" className="[--avatar-size:3.5rem]">
      <AvatarImage src={value.avatar} alt="" />
      <AvatarFallback>{value.name.charAt(0)}</AvatarFallback>
    </Avatar>
    <div className="flex min-w-0 flex-1 flex-col gap-0.5">
      <div className="flex items-center gap-related">
        <h2 className="text-title font-semibold">{value.name}</h2>
        <Badge variant="info">{value.plan}</Badge>
      </div>
      <p className="text-caption text-muted-foreground">
        {value.email} · {value.memberSince}
      </p>
    </div>
    <Button variant="outline" size="sm">
      Change photo
    </Button>
  </div>
);

const SettingsForm = ({ initial }: { initial: Settings }) => {
  const timezoneId = useId();
  const form = useAppForm({ defaultValues: initial });

  return (
    <Form form={form}>
      <FieldGroup>
        <form.AppField
          name="displayName"
          validators={{
            onDynamic: ({ value }) => (value.trim() === "" ? "Enter a display name." : undefined),
          }}
        >
          {(field) => <field.TextField label="Display name" autoComplete="name" required />}
        </form.AppField>
        <form.AppField name="timezone">
          {(field) => (
            <field.Field>
              <FieldLabel htmlFor={timezoneId}>Time zone</FieldLabel>
              <Select
                items={timezones}
                value={field.state.value}
                onValueChange={(value) => {
                  field.handleChange(value ?? initial.timezone);
                }}
              >
                <SelectTrigger id={timezoneId} className="w-full" onBlur={field.handleBlur}>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectGroup>
                    {timezones.map((timezone) => (
                      <SelectItem key={timezone.value} value={timezone.value}>
                        {timezone.label}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
            </field.Field>
          )}
        </form.AppField>
        <form.AppField name="securityAlerts">
          {(field) => (
            <field.SwitchField
              label="Security alerts"
              description="Email me when someone signs in from a new device."
            />
          )}
        </form.AppField>
        <form.AppField name="productUpdates">
          {(field) => <field.SwitchField label="Product updates" />}
        </form.AppField>
        <form.SubmitButton className="self-start">Save changes</form.SubmitButton>
      </FieldGroup>
    </Form>
  );
};

const SessionList = ({ value }: { value: Session[] }) => (
  <ItemGroup>
    {value.map((session) => (
      <Item key={session.id} size="sm" variant="card">
        <ItemMedia variant="icon">
          <Icon name="globe" aria-hidden="true" />
        </ItemMedia>
        <ItemContent>
          <ItemTitle>
            {session.device}
            {session.current ? <Badge variant="success">This device</Badge> : null}
          </ItemTitle>
          <ItemDescription>
            {session.location} · {session.lastActive}
          </ItemDescription>
        </ItemContent>
        {session.current ? null : (
          <ItemActions>
            <Button variant="ghost" size="sm">
              Sign out
            </Button>
          </ItemActions>
        )}
      </Item>
    ))}
  </ItemGroup>
);

interface AccountSettingsProps {
  /** How long each section's request takes, in milliseconds. The sections answer in turn. */
  latency?: number;
  /** The sessions request fails, while the other sections load. */
  failSessions?: boolean;
}

const AccountSettings = ({ latency = 1200, failSessions = false }: AccountSettingsProps) => {
  const accountRequest = useSimulatedFetch(account, { latency });
  const settingsRequest = useSimulatedFetch(settings, { latency: latency * 1.5 });
  const sessionsRequest = useSimulatedFetch(sessions, { fail: failSessions, latency: latency * 2 });

  return (
    <div className="flex w-full flex-col gap-section">
      <Skeleton
        data={accountRequest.data}
        sample={sampleAccount}
        loading={accountRequest.loading}
        id="account-settings-profile"
        label="Loading profile"
      >
        {(value) => <ProfileHeader value={value} />}
      </Skeleton>
      <Card>
        <CardHeader>
          <CardTitle>Preferences</CardTitle>
          <CardDescription>How your name appears and when we contact you.</CardDescription>
        </CardHeader>
        <CardContent>
          <Skeleton
            data={settingsRequest.data}
            sample={sampleSettings}
            loading={settingsRequest.loading}
            id="account-settings-preferences"
            label="Loading preferences"
          >
            {(value) => <SettingsForm initial={value} />}
          </Skeleton>
        </CardContent>
      </Card>
      <Card>
        <CardHeader>
          <CardTitle>Sessions</CardTitle>
          <CardDescription>Devices signed in to your account.</CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col gap-group">
          <Skeleton
            data={sessionsRequest.data}
            sample={sampleSessions}
            loading={sessionsRequest.loading}
            error={sessionsRequest.error}
            id="account-settings-sessions"
            label="Loading sessions"
          >
            {(value) => <SessionList value={value} />}
          </Skeleton>
          {sessionsRequest.error === undefined ? null : (
            <Button
              variant="outline"
              size="sm"
              className="self-start"
              onClick={() => {
                sessionsRequest.reload();
              }}
            >
              Try again
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export { AccountSettings };

export type { AccountSettingsProps };

import { AccountSettings } from "../helpers";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <AccountSettings />
  </div>
);

export default Example;

import { AccountSettings } from "../helpers";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <AccountSettings failSessions />
  </div>
);

export default Example;

import { AccountSettings } from "../helpers";
import type { AccountSettingsProps } from "../helpers";

const Example = ({ latency, failSessions }: AccountSettingsProps) => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    {/* Remounted when the args change, so each change replays the page load. */}
    <AccountSettings
      key={`${String(latency)}-${String(failSessions)}`}
      latency={latency}
      failSessions={failSessions}
    />
  </div>
);

export default Example;

import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import { useEffect, useState } from "react";

/*
 * A stand-in for a data request, so loading examples show the skeleton and then the reveal. In an
 * app the data comes from a route loader, TanStack Query or `use(promise)`; the UI only needs the
 * value and whether a request is in flight.
 */

/** How long the example "server" takes to answer, in milliseconds. */
const defaultLatency = 1600;

interface SimulatedFetchOptions {
  latency?: number;
  /** The request rejects instead of resolving. */
  fail?: boolean;
}

interface SimulatedFetch<T> {
  /** The loaded value; `undefined` until the first response. */
  data: T | undefined;
  /** A request is in flight, the first one or a refetch. */
  loading: boolean;
  error: Error | undefined;
  /** Drops the data and loads again, as on a first visit. */
  reload: () => void;
  /** Loads again while the current data stays on screen. */
  refetch: () => void;
}

const useSimulatedFetch = <T,>(
  value: T,
  { latency = defaultLatency, fail = false }: SimulatedFetchOptions = {},
): SimulatedFetch<T> => {
  const [request, setRequest] = useState({ id: 0 });

  // What the last response answered: the request and the value it was for. A new value (say, a new
  // page or sort order) is a new request, while the last response stays on screen.
  const [settled, setSettled] = useState<{
    id: number;
    value: T;
    data?: T;
    error?: Error;
  } | null>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setSettled(
        fail
          ? { error: new Error("The server did not respond. Try again."), id: request.id, value }
          : { data: value, id: request.id, value },
      );
    }, latency);

    return () => {
      clearTimeout(timer);
    };
  }, [request, latency, fail, value]);

  const current = settled?.id === request.id && settled.value === value ? settled : null;
  // `reload` clears the last response, so only refetches keep data on screen.
  const previous = settled?.data;

  return {
    data: current === null ? previous : current.data,
    error: current?.error,
    loading: current === null,
    refetch: () => {
      setRequest((last) => ({ id: last.id + 1 }));
    },
    reload: () => {
      setSettled(null);
      setRequest((last) => ({ id: last.id + 1 }));
    },
  };
};

/** Replays the example's request: `Reload` from nothing, `Refetch` over the data on screen. */
const LoadingControls = ({
  loading,
  reload,
  refetch,
}: Pick<SimulatedFetch<unknown>, "loading" | "reload" | "refetch">) => (
  <ButtonGroup aria-label="Replay the request">
    <Button variant="outline" size="sm" onClick={reload} disabled={loading}>
      Reload
    </Button>
    <Button variant="outline" size="sm" onClick={refetch} disabled={loading}>
      Refetch
    </Button>
  </ButtonGroup>
);

/** Playground controls shared by loading examples. */
const latencyArgType = {
  latency: { control: { max: 5000, min: 0, step: 100, type: "number" } },
} as const;

export { defaultLatency, latencyArgType, LoadingControls, useSimulatedFetch };

export type { SimulatedFetch, SimulatedFetchOptions };

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);
